                        if (doc->ext_flags & HOEDOWN_EXT_SPECIAL_ATTRIBUTE) {
                                len = parse_attributes(work->data, work->size, attr, attribute, "list", 4, 0, doc->attr_activation);
                        } else {
                                len = work->size;
                        }
                        parse_inline(inter, doc, work->data, len);
